package in.malabartrails; import jakarta.persistence.*;import java.time.OffsetDateTime;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity @Table(name="package_versions") public class PackageVersion { @Id @GeneratedValue(strategy=GenerationType.UUID) public UUID id; @Column(name="package_id",nullable=false) public UUID packageId; @Column(nullable=false) public int version; @JdbcTypeCode(SqlTypes.JSON) @Column(nullable=false,columnDefinition="jsonb") public String snapshot; @Column(name="editor_email",nullable=false) public String editorEmail; @Column(name="created_at",insertable=false,updatable=false) public OffsetDateTime createdAt; }
